-- The IB fold's live side (SkyInkberry, 2026-11-01, on the AP fold's pattern; Open Asks Sheet 150 card 1).
-- Re-points 4 saved title assignments from a twin to IB's own subject name and 4 issuer assignments to one IB
-- issuer name, so the nightly fold matches kb/unified_titles.json and kb/credentials.json after this PR's merge.
-- Guarded: a row changes only while it still holds its before-value. Before-values and the rollback:
-- ib_kb_curation_update_receipt.json beside this file. Expect 8 rows returned.
with m(course_id,field,before,after) as (values ('_UNCLASSIFIED::IB English B HL (Minimum Passing Score of 4)','unified_title_assignment','IB Language B: English HL','IB Language B HL'),('_UNCLASSIFIED::IB English Lit (A1) HL (Minimum Passing Score of 4)','unified_title_assignment','IB Language A1: English HL','IB Language A: Literature HL'),('_UNCLASSIFIED::IB Global Politics','unified_title_assignment','IB Global Politics','IB Global Politics HL'),('_UNCLASSIFIED::IB World Religions HL','unified_title_assignment','IB World Religions HL','IB World Religions SL'),('_UNCLASSIFIED::IB Language B - any language except English HL','issuing_agency_assignment','International Baccalaureate (IB)','International Baccalaureate Organization (IBO)'),('_UNCLASSIFIED::IB Language B - any language HL - Score of 4 or higher - HISTORICAL Type 1','issuing_agency_assignment','International Baccalaureate (IB)','International Baccalaureate Organization (IBO)'),('_UNCLASSIFIED::IB Language B - any language HL - Score of 4 or higher - HISTORICAL Type 2','issuing_agency_assignment','International Baccalaureate (IB)','International Baccalaureate Organization (IBO)'),('_UNCLASSIFIED::IB Language B (any language) HL (Score of 4 or higher)','issuing_agency_assignment','International Baccalaureate (IB)','International Baccalaureate Organization (IBO)')) update kb_curation k set value=m.after, reviewer_email='cer-ib-fold-skyinkberry@bot', reviewed_at=now() from m where k.course_id=m.course_id and k.field=m.field and k.value=m.before returning k.course_id, k.field, k.value;
